import{_ as e,o as s,c as o,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"es/nay-lib/index.md","filePath":"es/nay-lib/index.md"}'),r={name:"es/nay-lib/index.md"};function i(t,a,l,d,c,p){return s(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p><code>nay_lib</code> es la biblioteca común en la que se apoyan todos los scripts Nayretis. La recibes con cada compra, la instalas una sola vez y todos los scripts Nayretis que añadas la usan.</p><h2 id="que-te-aporta" tabindex="-1">Qué te aporta <a class="header-anchor" href="#que-te-aporta" aria-label="Permalink to &quot;Qué te aporta&quot;">​</a></h2><ul><li><strong>Un único panel de ajustes</strong>, <code>/nay</code>, para todos los scripts Nayretis. Los ajustes se guardan en tu base de datos y se aplican a todos los jugadores en cuanto guardas. Consulta <a href="/es/nay-lib/panel">Panel /nay</a>.</li><li><strong>Permisos</strong> por ACE o por identificador Discord, Steam, FiveM o license. Consulta <a href="/es/nay-lib/permissions">Permisos</a>.</li><li><strong>Seis idiomas</strong>: inglés, francés, español, portugués, polaco y alemán. Una traducción que falta se muestra en inglés.</li><li><strong>Bridge de frameworks</strong>: ESX Legacy, QBCore, QBox y ox_core detectados automáticamente, con sus inventarios, targets y notificaciones. Consulta <a href="/es/bridge/">Bridge</a>.</li><li><strong>API HTTP</strong> para tu web, tu panel de control o tu bot de Discord, desactivada por defecto. Consulta <a href="/es/nay-lib/api">API HTTP</a>.</li><li><strong>Webhooks</strong>, incluidos mensajes de Discord, para los eventos de los scripts. Consulta <a href="/es/nay-lib/webhooks">Webhooks</a>.</li><li><strong>Registro de auditoría</strong> de cada cambio hecho en el juego, desde la consola o a través de la API. Consulta <a href="/es/nay-lib/audit">Registro de auditoría</a>.</li><li>Notificaciones, avisos de texto y barras de progreso de Nayretis, compartidos por todos los scripts.</li></ul><h2 id="requisitos-y-orden-de-arranque" tabindex="-1">Requisitos y orden de arranque <a class="header-anchor" href="#requisitos-y-orden-de-arranque" aria-label="Permalink to &quot;Requisitos y orden de arranque&quot;">​</a></h2><p>La única dependencia es <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Inicia <code>nay_lib</code> después de los recursos de tu framework, inventario y target, y antes de todos los scripts Nayretis:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>Las tablas se crean en el primer arranque. Las opciones del servidor que van en <code>server.cfg</code> se indican en la página <a href="/es/nay-lib/convars">Convars</a>.</p>`,8)])])}const b=e(r,[["render",i]]);export{g as __pageData,b as default};
